// 1. 被驱动端口 - 核心域定义接口
public interface OrderRepository {
    Order findById(OrderId id);
    void save(Order order);
    List<Order> findByCustomerId(CustomerId customerId);
}

public interface PaymentGateway {
    PaymentResult charge(PaymentRequest request);
}

// 2. 核心域 - 不依赖任何外部
public class OrderService {
    private final OrderRepository orderRepo; // 端口
    private final PaymentGateway paymentGateway; // 端口

    public OrderService(OrderRepository orderRepo, PaymentGateway paymentGateway) {
        this.orderRepo = orderRepo;
        this.paymentGateway = paymentGateway;
    }

    public OrderId placeOrder(PlaceOrderCmd cmd) {
        Order order = Order.create(cmd.getItems(), cmd.getCustomerId());
        orderRepo.save(order);
        return order.getId();
    }
}

// 3. 被驱动适配器 - 实现端口
@Repository
public class JpaOrderRepository implements OrderRepository {
    private final OrderJpaRepo jpaRepo;

    @Override
    public Order findById(OrderId id) {
        OrderEntity entity = jpaRepo.findById(id.getValue())
            .orElseThrow(() -> new NotFoundException("订单不存在"));
        return OrderMapper.toDomain(entity);
    }

    @Override
    public void save(Order order) {
        OrderEntity entity = OrderMapper.toEntity(order);
        jpaRepo.save(entity);
    }
}

// 4. 驱动适配器 - Controller
@RestController
@RequestMapping("/orders")
public class OrderController {
    private final OrderService orderService; // 驱动端口

    @PostMapping
    public OrderIdVO create(@RequestBody CreateOrderReq req) {
        OrderId id = orderService.placeOrder(req.toCmd());
        return new OrderIdVO(id);
    }
}

// 5. 测试 - 不需要任何外部依赖
@Test
void shouldPlaceOrder() {
    OrderRepository mockRepo = mock(OrderRepository.class);
    PaymentGateway mockGateway = mock(PaymentGateway.class);
    OrderService service = new OrderService(mockRepo, mockGateway);

    OrderId id = service.placeOrder(new PlaceOrderCmd(...));
    assertNotNull(id);
    verify(mockRepo).save(any());
}
